import{_ as d,o as a,c as e,a3 as r}from"./chunks/framework.CRbjHCyB.js";const g=JSON.parse('{"title":"功能概览","description":"","frontmatter":{},"headers":[],"relativePath":"zh/clice/features/overview.md","filePath":"zh/clice/features/overview.md"}'),i={name:"zh/clice/features/overview.md"};function n(o,t,l,s,h,c){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="功能概览" tabindex="-1">功能概览 <a class="header-anchor" href="#功能概览" aria-label="Permalink to &quot;功能概览&quot;">​</a></h1><p>clice 提供一套基于 LLVM/Clang 构建的 C++ 开发工具。本节介绍已实现和计划中的功能，并提供相关上游问题的链接。</p><h2 id="lsp-编辑器功能" tabindex="-1">LSP 编辑器功能 <a class="header-anchor" href="#lsp-编辑器功能" aria-label="Permalink to &quot;LSP 编辑器功能&quot;">​</a></h2><p>将 clice 用作编辑器后端时可用的语言服务器协议功能。</p><table tabindex="0"><thead><tr><th>功能</th><th>状态</th><th>页面</th></tr></thead><tbody><tr><td>代码补全</td><td>31 项支持</td><td><a href="./completion">completion</a></td></tr><tr><td>悬停</td><td>34 项支持 · 21 项部分支持 · 11 项不支持</td><td><a href="./hover">hover</a></td></tr><tr><td>签名帮助</td><td>14 项支持</td><td><a href="./signature-help">signature-help</a></td></tr><tr><td>代码导航</td><td>44 项支持 · 14 项部分支持 · 34 项不支持</td><td><a href="./navigation">navigation</a></td></tr><tr><td>文档链接</td><td>7 项支持 · 1 项部分支持 · 1 项不支持</td><td><a href="./document-links">document-links</a></td></tr><tr><td>语义 Token</td><td>54 项支持 · 4 项部分支持 · 10 项不支持</td><td><a href="./semantic-tokens">semantic-tokens</a></td></tr><tr><td>内联提示</td><td>31 项支持 · 6 项部分支持 · 4 项不支持</td><td><a href="./inlay-hints">inlay-hints</a></td></tr><tr><td>折叠范围</td><td>13 项支持 · 2 项部分支持 · 6 项不支持</td><td><a href="./folding-ranges">folding-ranges</a></td></tr><tr><td>文档符号</td><td>18 项支持 · 2 项部分支持 · 7 项不支持</td><td><a href="./document-symbols">document-symbols</a></td></tr><tr><td>格式化</td><td>已实现</td><td><a href="./formatting">formatting</a></td></tr><tr><td>诊断</td><td>部分支持</td><td><a href="./diagnostics">diagnostics</a></td></tr><tr><td>代码操作</td><td>存根</td><td><a href="./code-action">code-action</a></td></tr></tbody></table><h2 id="lint" tabindex="-1">Lint <a class="header-anchor" href="#lint" aria-label="Permalink to &quot;Lint&quot;">​</a></h2><p>由 clang-tidy 驱动的项目级静态分析，并采用 clice 独有的跨 TU 优化。</p><table tabindex="0"><thead><tr><th>功能</th><th>状态</th><th>页面</th></tr></thead><tbody><tr><td>clang-tidy 集成</td><td>部分支持</td><td><a href="./lint">lint</a></td></tr></tbody></table><p>项目级 CLI（<code>clice lint</code>）已实现；编辑器内实时 诊断和跨 TU 去重仍在计划中。</p><h2 id="图例" tabindex="-1">图例 <a class="header-anchor" href="#图例" aria-label="Permalink to &quot;图例&quot;">​</a></h2><p>由测试夹具（fixture）支撑的功能，会按状态统计其测试语料库所固定的已记录能力：</p><ul><li><strong>支持</strong> — 该能力可用；快照（snapshot）固定其行为</li><li><strong>部分支持</strong> — 尚不完整；快照固定目前可用的行为</li><li><strong>不支持</strong> — 已记录的功能缺口，已跟踪但尚未实现</li></ul><p>尚未纳入 fixture 管线的功能仍使用手动指定的标签：</p><ul><li><strong>已实现</strong> — 核心功能可用，仅有少量不足</li><li><strong>部分支持</strong> — 关键子系统缺失（如模块支持）</li><li><strong>存根</strong> — 处理器已存在，但返回空结果/null</li><li><strong>计划中</strong> — 已完成设计，但尚未实现</li></ul>',14)])])}const p=d(i,[["render",n]]);export{g as __pageData,p as default};
